import{c as e,Q as n,j as i,m as t}from"./chunks/framework.BnKG8mJY.js";const k=JSON.parse('{"title":"Log Perubahan Sistem - 21 Januari 2026","description":"","frontmatter":{},"headers":[],"relativePath":"changelog/UPDATE_LOG_2026-01-21.md","filePath":"changelog/UPDATE_LOG_2026-01-21.md"}'),r={name:"changelog/UPDATE_LOG_2026-01-21.md"};function s(o,a,l,d,u,m){return n(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="log-perubahan-sistem-21-januari-2026" tabindex="-1">Log Perubahan Sistem - 21 Januari 2026 <a class="header-anchor" href="#log-perubahan-sistem-21-januari-2026" aria-label="Permalink to &quot;Log Perubahan Sistem - 21 Januari 2026&quot;">​</a></h1><p>Dokumen ini merangkum perubahan yang dilakukan pada modul Master Admin dan pengaturan hak akses role (Mekanik).</p><h2 id="_1-modul-master-admin" tabindex="-1">1. Modul Master Admin <a class="header-anchor" href="#_1-modul-master-admin" aria-label="Permalink to &quot;1. Modul Master Admin&quot;">​</a></h2><h3 id="frontend-tailadmin-vuejs-1-0-0-src-views-master-adminmaster-vue" tabindex="-1">Frontend (<code>tailadmin-vuejs-1.0.0/src/views/Master/AdminMaster.vue</code>) <a class="header-anchor" href="#frontend-tailadmin-vuejs-1-0-0-src-views-master-adminmaster-vue" aria-label="Permalink to &quot;Frontend (`tailadmin-vuejs-1.0.0/src/views/Master/AdminMaster.vue`)&quot;">​</a></h3><ul><li><strong>Penambahan Kolom Data</strong>: <ul><li>Menambahkan kolom <strong>Email</strong>, <strong>No Telepon</strong>, dan <strong>Jabatan</strong> pada tabel daftar admin.</li><li>Menambahkan input field untuk ketiga data tersebut pada formulir Tambah/Edit Admin.</li></ul></li><li><strong>Penyusunan Ulang Layout Toolbar</strong>: <ul><li>Memindahkan <em>Search Bar</em> ke sebelah kiri.</li><li>Mengelompokkan tombol aksi (<em>Tambah Admin</em>, <em>Import</em>, dll) ke sebelah kanan.</li><li>Memindahkan informasi <em>Total Data</em> ke baris bawah toolbar.</li></ul></li><li><strong>Perbaikan Form Input</strong>: <ul><li>Mengubah field <strong>NIK</strong> menjadi <em>editable</em> (sebelumnya <em>readonly</em>).</li><li>Menambahkan penanganan pesan error dari backend agar notifikasi (&quot;Data NIK sudah ada...&quot;) muncul dengan benar di <em>Toast</em>.</li></ul></li></ul><h3 id="backend-node-backend-routes-admin-js" tabindex="-1">Backend (<code>node_backend/routes/admin.js</code>) <a class="header-anchor" href="#backend-node-backend-routes-admin-js" aria-label="Permalink to &quot;Backend (`node_backend/routes/admin.js`)&quot;">​</a></h3><ul><li><strong>Sinkronisasi Database</strong>: <ul><li>Memperbarui query <code>SELECT</code>, <code>INSERT</code>, dan <code>UPDATE</code> untuk menyertakan kolom <code>email</code>, <code>nomor_telp</code>, dan <code>jabatan</code>.</li></ul></li><li><strong>Validasi Data</strong>: <ul><li>Menambahkan validasi sisi server untuk mencegah duplikasi <strong>NIK</strong>.</li><li>Validasi bersifat <em>case-insensitive</em> (misal: &quot;clc003&quot; dianggap sama dengan &quot;CLC003&quot;).</li><li>Menetapkan pesan error khusus: <em>&quot;Data NIK sudah ada, tolong cek kembali&quot;</em>.</li></ul></li></ul><h2 id="_2-hak-akses-role-mekanik" tabindex="-1">2. Hak Akses &amp; Role (Mekanik) <a class="header-anchor" href="#_2-hak-akses-role-mekanik" aria-label="Permalink to &quot;2. Hak Akses &amp; Role (Mekanik)&quot;">​</a></h2><h3 id="navigasi-sidebar-tailadmin-vuejs-1-0-0-src-config-navigation-js" tabindex="-1">Navigasi Sidebar (<code>tailadmin-vuejs-1.0.0/src/config/navigation.js</code>) <a class="header-anchor" href="#navigasi-sidebar-tailadmin-vuejs-1-0-0-src-config-navigation-js" aria-label="Permalink to &quot;Navigasi Sidebar (`tailadmin-vuejs-1.0.0/src/config/navigation.js`)&quot;">​</a></h3><ul><li><strong>Filter Menu Khusus Mekanik</strong>: <ul><li><strong>Master</strong>: Menu disembunyikan sepenuhnya.</li><li><strong>Transaksi</strong>: Hanya menampilkan sub-menu <strong>Repair</strong>. Menu <em>Sales Cost</em> dan <em>Subcontractor</em> disembunyikan.</li></ul></li></ul><h3 id="proteksi-rute-tailadmin-vuejs-1-0-0-src-router-index-ts" tabindex="-1">Proteksi Rute (<code>tailadmin-vuejs-1.0.0/src/router/index.ts</code>) <a class="header-anchor" href="#proteksi-rute-tailadmin-vuejs-1-0-0-src-router-index-ts" aria-label="Permalink to &quot;Proteksi Rute (`tailadmin-vuejs-1.0.0/src/router/index.ts`)&quot;">​</a></h3><ul><li><strong>Route Guards</strong>: <ul><li>Menambahkan properti <code>meta.roles</code> pada rute-rute transaksi.</li><li><strong>Repair</strong>: Dapat diakses oleh <code>[&#39;admin&#39;, &#39;user&#39;, &#39;mekanik&#39;]</code>.</li><li><strong>Sales Cost &amp; Subcontractor</strong>: Hanya dapat diakses oleh <code>[&#39;admin&#39;, &#39;user&#39;]</code>.</li></ul></li><li><strong>Redirect Otomatis</strong>: <ul><li>Jika user dengan role <strong>Mekanik</strong> mencoba mengakses halaman terlarang (via URL langsung), sistem akan otomatis mengalihkan ke halaman <code>/repair</code>.</li></ul></li></ul>',12)])])}const g=e(r,[["render",s]]);export{k as __pageData,g as default};
